/bin/zsh -lc "rg -n '152512-080' docs/paivakirjat; python3 - <<'PY'
import zipfile,xml.etree.ElementTree as E,glob
ns={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
for p in glob.glob('docs/liitteet/*'):
 print('\\nFILE',p)
 with zipfile.ZipFile(p) as z:
  strings=[]
  if 'xl/sharedStrings.xml' in z.namelist():
   strings=[''.join(s.itertext()) for s in E.fromstring(z.read('xl/sharedStrings.xml'))]
  print(z.read('xl/workbook.xml').decode())
  for name in z.namelist():
   if name.startswith('xl/worksheets/sheet') and name.endswith('.xml'):
    print(name)
    for row in E.fromstring(z.read(name)).findall('.//s:row',ns):
     out=[]
     for c in row:
      v=c.find('s:v',ns)
      val=v.text if v is not None else ''.join(c.itertext())
      if c.get('t')=='s': val=strings[int(val)]
      out.append(c.get('r')+': '+str(val))
     print(' | '.join(out))
PY"

